  if (result && typeof result === 'object') {
    deepMerge(output, result);
  } else {
    output.result = result;
  }
  output.status = 'completed';
  output.timestamp = new Date().toISOString();
} catch (err) {
  output.status = 'error';
  output.error = err.message;
}
return output;

